    "helpers": "static void mergeSort(int[] a, int inicio, int fin) {\n  if (inicio >= fin) return;\n  int medio = inicio + (fin - inicio) / 2;\n  mergeSort(a, inicio, medio); mergeSort(a, medio + 1, fin);\n  int[] temp = new int[fin - inicio + 1];\n  int i = inicio, j = medio + 1, k = 0;\n  while (i <= medio && j <= fin) temp[k++] = a[i] <= a[j] ? a[i++] : a[j++];\n  while (i <= medio) temp[k++] = a[i++];\n  while (j <= fin) temp[k++] = a[j++];\n  System.arraycopy(temp, 0, a, inicio, temp.length);\n}",
    "code": "// RCC | Ejemplo independiente de Java 17\n// Guarda este archivo como Main.java; compila con javac Main.java y ejecuta java Main.\nimport java.util.*;\nimport java.math.*;\nimport java.time.*;\nimport java.time.temporal.ChronoUnit;\nimport java.nio.file.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\nimport java.util.regex.*;\nimport java.util.stream.*;\npublic class Main {\n  public static void main(String[] args) throws Exception {\n    int[] datos = {38, 27, 43, 3, 9, 82, 10};\n    mergeSort(datos, 0, datos.length - 1);\n    System.out.println(Arrays.toString(datos));\n  }\n  static void mergeSort(int[] a, int inicio, int fin) {\n    if (inicio >= fin) return;\n    int medio = inicio + (fin - inicio) / 2;\n    mergeSort(a, inicio, medio); mergeSort(a, medio + 1, fin);\n    int[] temp = new int[fin - inicio + 1];\n    int i = inicio, j = medio + 1, k = 0;\n    while (i <= medio && j <= fin) temp[k++] = a[i] <= a[j] ? a[i++] : a[j++];\n    while (i <= medio) temp[k++] = a[i++];\n    while (j <= fin) temp[k++] = a[j++];\n    System.arraycopy(temp, 0, a, inicio, temp.length);\n  }\n}\n",
