    "premium": true,
    "description": "Calcula distancias mínimas en un grafo con pesos no negativos.",
    "body": "Map<String, Map<String, Integer>> g = new HashMap<>();\ng.put(\"A\", Map.of(\"B\", 4, \"C\", 2)); g.put(\"B\", Map.of(\"D\", 5)); g.put(\"C\", Map.of(\"B\", 1, \"D\", 8)); g.put(\"D\", Map.of());\nMap<String, Integer> dist = new HashMap<>();\nPriorityQueue<String[]> pq = new PriorityQueue<>(Comparator.comparingInt(x -> Integer.parseInt(x[1])));\ndist.put(\"A\", 0); pq.offer(new String[]{\"A\", \"0\"});\nwhile (!pq.isEmpty()) {\n  String[] item = pq.poll(); String u = item[0]; int d = Integer.parseInt(item[1]);\n  if (d != dist.get(u)) continue;\n  for (var edge : g.getOrDefault(u, Map.of()).entrySet()) {\n    int next = d + edge.getValue();\n    if (next < dist.getOrDefault(edge.getKey(), Integer.MAX_VALUE)) {\n      dist.put(edge.getKey(), next); pq.offer(new String[]{edge.getKey(), String.valueOf(next)});\n    }\n  }\n}\nSystem.out.println(dist);",
    "helpers": "",
    "code": "// RCC | Ejemplo independiente de Java 17\n// Guarda este archivo como Main.java; compila con javac Main.java y ejecuta java Main.\nimport java.util.*;\nimport java.math.*;\nimport java.time.*;\nimport java.time.temporal.ChronoUnit;\nimport java.nio.file.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\nimport java.util.regex.*;\nimport java.util.stream.*;\npublic class Main {\n  public static void main(String[] args) throws Exception {\n    Map<String, Map<String, Integer>> g = new HashMap<>();\n    g.put(\"A\", Map.of(\"B\", 4, \"C\", 2)); g.put(\"B\", Map.of(\"D\", 5)); g.put(\"C\", Map.of(\"B\", 1, \"D\", 8)); g.put(\"D\", Map.of());\n    Map<String, Integer> dist = new HashMap<>();\n    PriorityQueue<String[]> pq = new PriorityQueue<>(Comparator.comparingInt(x -> Integer.parseInt(x[1])));\n    dist.put(\"A\", 0); pq.offer(new String[]{\"A\", \"0\"});\n    while (!pq.isEmpty()) {\n      String[] item = pq.poll(); String u = item[0]; int d = Integer.parseInt(item[1]);\n      if (d != dist.get(u)) continue;\n      for (var edge : g.getOrDefault(u, Map.of()).entrySet()) {\n        int next = d + edge.getValue();\n        if (next < dist.getOrDefault(edge.getKey(), Integer.MAX_VALUE)) {\n          dist.put(edge.getKey(), next); pq.offer(new String[]{edge.getKey(), String.valueOf(next)});\n        }\n      }\n    }\n    System.out.println(dist);\n  }\n}\n",
