    "helpers": "static class UnionFind {\n  int[] parent, size;\n  UnionFind(int n) { parent=new int[n]; size=new int[n]; for(int i=0;i<n;i++){parent[i]=i;size[i]=1;} }\n  int find(int x) { if(parent[x]!=x) parent[x]=find(parent[x]); return parent[x]; }\n  void union(int a,int b) { a=find(a); b=find(b); if(a==b)return; if(size[a]<size[b]){int t=a;a=b;b=t;} parent[b]=a; size[a]+=size[b]; }\n  boolean connected(int a,int b) { return find(a)==find(b); }\n}",
    "code": "// RCC | Ejemplo independiente de Java 17\n// Guarda este archivo como Main.java; compila con javac Main.java y ejecuta java Main.\nimport java.util.*;\nimport java.math.*;\nimport java.time.*;\nimport java.time.temporal.ChronoUnit;\nimport java.nio.file.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\nimport java.util.regex.*;\nimport java.util.stream.*;\npublic class Main {\n  public static void main(String[] args) throws Exception {\n    UnionFind uf = new UnionFind(6);\n    uf.union(0, 1); uf.union(1, 2); uf.union(4, 5);\n    System.out.println(uf.connected(0, 2));\n    System.out.println(uf.connected(0, 5));\n  }\n  static class UnionFind {\n    int[] parent, size;\n    UnionFind(int n) { parent=new int[n]; size=new int[n]; for(int i=0;i<n;i++){parent[i]=i;size[i]=1;} }\n    int find(int x) { if(parent[x]!=x) parent[x]=find(parent[x]); return parent[x]; }\n    void union(int a,int b) { a=find(a); b=find(b); if(a==b)return; if(size[a]<size[b]){int t=a;a=b;b=t;} parent[b]=a; size[a]+=size[b]; }\n    boolean connected(int a,int b) { return find(a)==find(b); }\n  }\n}\n",
