    "helpers": "static class Trie {\n  static class Node { Map<Character,Node> next=new HashMap<>(); boolean word; }\n  private final Node root=new Node();\n  void add(String value) { Node n=root; for(char c:value.toCharArray()) n=n.next.computeIfAbsent(c,k->new Node()); n.word=true; }\n  boolean walk(String value, boolean requireWord) { Node n=root; for(char c:value.toCharArray()){n=n.next.get(c);if(n==null)return false;} return !requireWord||n.word; }\n  boolean contains(String value) { return walk(value,true); }\n  boolean startsWith(String prefix) { return walk(prefix,false); }\n}",
    "code": "// RCC | Ejemplo independiente de Java 17\n// Guarda este archivo como Main.java; compila con javac Main.java y ejecuta java Main.\nimport java.util.*;\nimport java.math.*;\nimport java.time.*;\nimport java.time.temporal.ChronoUnit;\nimport java.nio.file.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\nimport java.util.regex.*;\nimport java.util.stream.*;\npublic class Main {\n  public static void main(String[] args) throws Exception {\n    Trie trie = new Trie();\n    trie.add(\"roblox\"); trie.add(\"robot\"); trie.add(\"ruby\");\n    System.out.println(trie.contains(\"robot\"));\n    System.out.println(trie.startsWith(\"ro\"));\n  }\n  static class Trie {\n    static class Node { Map<Character,Node> next=new HashMap<>(); boolean word; }\n    private final Node root=new Node();\n    void add(String value) { Node n=root; for(char c:value.toCharArray()) n=n.next.computeIfAbsent(c,k->new Node()); n.word=true; }\n    boolean walk(String value, boolean requireWord) { Node n=root; for(char c:value.toCharArray()){n=n.next.get(c);if(n==null)return false;} return !requireWord||n.word; }\n    boolean contains(String value) { return walk(value,true); }\n    boolean startsWith(String prefix) { return walk(prefix,false); }\n  }\n}\n",
