    "id": "rcc_java_30_sliding_window",
    "name": "Java: Máximo de ventana deslizante",
    "topic": "Algoritmos",
    "level": "Avanzado",
    "premium": true,
    "description": "Encuentra el máximo de cada ventana usando un deque de índices.",
    "body": "int[] a = {1,3,-1,-3,5,3,6,7}; int k=3;\nDeque<Integer> q = new ArrayDeque<>(); List<Integer> maximos=new ArrayList<>();\nfor(int i=0;i<a.length;i++) {\n  while(!q.isEmpty() && q.peekFirst()<=i-k) q.pollFirst();\n  while(!q.isEmpty() && a[q.peekLast()]<=a[i]) q.pollLast();\n  q.offerLast(i);\n  if(i>=k-1) maximos.add(a[q.peekFirst()]);\n}\nSystem.out.println(maximos);",
    "helpers": "",
    "code": "// RCC | Ejemplo independiente de Java 17\n// Guarda este archivo como Main.java; compila con javac Main.java y ejecuta java Main.\nimport java.util.*;\nimport java.math.*;\nimport java.time.*;\nimport java.time.temporal.ChronoUnit;\nimport java.nio.file.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\nimport java.util.regex.*;\nimport java.util.stream.*;\npublic class Main {\n  public static void main(String[] args) throws Exception {\n    int[] a = {1,3,-1,-3,5,3,6,7}; int k=3;\n    Deque<Integer> q = new ArrayDeque<>(); List<Integer> maximos=new ArrayList<>();\n    for(int i=0;i<a.length;i++) {\n      while(!q.isEmpty() && q.peekFirst()<=i-k) q.pollFirst();\n      while(!q.isEmpty() && a[q.peekLast()]<=a[i]) q.pollLast();\n      q.offerLast(i);\n      if(i>=k-1) maximos.add(a[q.peekFirst()]);\n    }\n    System.out.println(maximos);\n  }\n}\n",
